public class ImagenFija extends Trabajo {

    //El constructor vacío que tiene la clase.

    public ImagenFija() {
		//Super: Manda a traer lo demás de lo que ya se tiene
        super();
    }

    // Constructor default
    public ImagenFija(String codigo, String estudio, String nombre, float horasEstimadas,boolean diurno) {
		//Super para traer datos
        super(codigo, estudio, nombre, horasEstimadas, diurno);
    }


    //Nuevo costo, se usa el Override para modificar lo demás. Como es solo horario, si diurno es true, 45. Si no, es 30.

    @Override
    public float calcularCosto() {

        if (diurno) {
            return 45.0f;
        }
        else {
            return 30.0f;
        }
    }

	//Override del tiempo de entrega. Depende de la hora entrega.

    @Override
    public int tiempoEntrega() {

        if (diurno) {
            return 4;
        }
        else {
            return 10;
        }
    }


    //redefinir intentos máximos.

    @Override
    public int maxIntentos() {

        return 3;
    }


    //Sobreestribir la categoría.

    @Override
    public String getCategoria() {

        return "Imagen Fija";
    }
}
